begin; do $$ begin if to_regclass('public._test_db_marker') is null then raise exception 'STOP: test DB marker not found. This SQL is only for the test project.'; end if; end; $$; do $$ declare t text; c bigint; total bigint := 0; begin if current_setting('class_rollback.confirm', true) is distinct from 'backed-up' then foreach t in array array['classes', 'class_schedules', 'class_students'] loop if to_regclass('public.' || t) is not null then execute format('select count(*) from public.%I', t) into c; total := total + c; end if; end loop; if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'students' and column_name = 'status') then execute 'select count(*) from public.students where status <> ''active'' or withdrawn_on is not null or withdraw_note is not null' into c; total := total + c; end if; if total > 0 then raise exception 'class rollback blocked: % rows would be lost. Back up first; see docs/class-management-plan.md section 6', total; end if; end if; end; $$; drop function if exists withdraw_student(uuid, date, text); drop table if exists class_students; drop table if exists class_schedules; drop table if exists classes; alter table students drop constraint if exists students_status_check; alter table students drop column if exists withdraw_note; alter table students drop column if exists withdrawn_on; alter table students drop column if exists status; commit;
